@pytest.mark.parametrize(('terminal', 'request_kind', 'constructor_raised', 'retry'), ( ('return', 'throw', False, True), ('return', 'close', False, False), ('raise', 'throw', False, False), ('raise', 'close', True, False))) def test_finished_frame_history_and_exact_new_request_reply_share_one_actual_chain( terminal, request_kind, constructor_raised, retry): program, model, details = finished_frame_identity_execution(terminal=terminal, request=request_kind, constructor_raised=constructor_raised, retry=retry, instances=2) index = _index(program, model, details) static = details['static'] finished = static['finished_request'] original = finished['original_terminal_driver'] source = next(row for row in program.operations if row.id == original['outcome_source']) assert source.terminator.kind is (TerminatorKind.RETURN if terminal == 'return' else TerminatorKind.RAISE) assert original['update'].post is SessionPost.COMPLETE assert details['objects'][0] != details['objects'][1] assert len(program.resumable_creates) == 1 assert len(model.body_drive_executions) == static['base_drive_count'] * 2 public = ProgramIndex(program) paths = public.request_no_drive_paths(finished['scope'].id, budget=_BUDGET) _finished_inventory(paths, finished) # Both real reply-construction outcomes remain in the original CFG. The # actual selected one is checked independently by _finished_capture below. for raised in (False, True): _ports(public, program, finished, _path(paths, finished, raised=raised), raised=raised) for ordinal, endpoint in enumerate(details['frame_identities']): _finished_capture(index, program, model, details, ordinal) view = index.body_state_history(endpoint['read'], budget=_BUDGET) assert view['expected_bool'] is True and view['observed_branch'] is True assert view['drive_inventory'] == program.body_drives assert view['commit_inventory'] == program.body_outcome_commits assert view['budget']['truncated'] is False candidate = _candidate(view, endpoint) assert candidate['commit'] == endpoint['publication'] assert candidate['post_established'] is candidate['expected_bool'] is True assert candidate['drive_support']['supported'] is True assert candidate['source_chain']['supported'] is candidate['read_chain']['supported'] is True assert candidate['source_chain']['root'] == candidate['read_chain']['root'] == endpoint['caller_activation'] assert candidate['terminal_route'] _guard(candidate['subject_binding']) _guard(candidate['source_subject_binding']) _guard(candidate['drive_support']['creation_binding']) assert candidate['terminal_scope'].applicability.value == 'UNKNOWN' assert candidate['content_preservation']['preserved'] is None assert _candidate(view, details['frame_identities'][1 - ordinal])['expected_bool'] is None assert all(view[flag] is False for flag in (*_FLAGS, 'native_phase_verified')) # Remove only the explicit endpoint catalog declarations on the same graph # and capture: observation and request metadata alone still do not prove F. plain = replace(model, denotations=()) plain_index = _index(program, plain, details) for endpoint in details['frame_identities']: view = plain_index.body_state_history(endpoint['read'], budget=_BUDGET) assert view['observed_branch'] is True and view['expected_bool'] is None assert view['drive_inventory'] == program.body_drives assert view['commit_inventory'] == program.body_outcome_commits > assert _candidate(view, endpoint)['post_established'] is True E assert None is True
